{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Experiment agent output v1 (A path)",
  "type": "object",
  "additionalProperties": false,
  "required": ["agent_id", "narrative", "state", "completion_declared"],
  "properties": {
    "agent_id": {"type": "string"},
    "narrative": {"type": "string"},
    "completion_declared": {"type": "boolean"},
    "state": {
      "type": "object",
      "additionalProperties": false,
      "required": ["open_issue_ids", "info_items"],
      "properties": {
        "open_issue_ids": {"type": ["array", "null"], "uniqueItems": true, "items": {"type": "string"}},
        "info_items": {"type": ["array", "null"], "items": {"type": "string"}},
        "proposal_values": {"type": ["object", "null"], "additionalProperties": {"type": "number"}},
        "reasons": {"type": "object", "additionalProperties": {"type": "string"}}
      }
    }
  }
}

